e bewoners van het seniorencomplex geen veilige afstand tot het geweld vormen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1725396/de-laatste-duivel-die-sterft.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789021498393","key":{"isbn_13":"9789021498393"},"before":null,"after":{"work_id":975100008,"title":"King of greed","isbn_13":"9789021498393","isbn_10":"9021498391","language":"nld","publisher":"Singel Uitgeverijen","id":975200078}},{"relation":"catalog_edition_metadata","ref":"metadata:9789021498393","key":{"edition_id":"@edition:9789021498393"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/1825358/king-of-greed.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1825358/king-of-greed.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000678554_King_of_greed_0_0.jpg","checkedAt":"2026-10-31T22:47:16.253Z","sha256":"4ee8ea10505f2a11ed2cf8830fde357927855ea58a41c4d54227e7db06f9ada7","bytes":405681,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789021498393","work_id":975100008,"bound_author_id":924300405,"bound_title":"King of greed","bound_language":"nld","bound_isbn13":"9789021498393","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000678554_King_of_greed_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1825358/king-of-greed.html"}},{"relation":"catalog_work_descriptions","ref":"description:1999:nl","key":{"work_id":975100008,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-c