19297/de-tomben-van-atuan.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1019297/de-tomben-van-atuan.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://www.standaardboekhandel.be/p/de-tomben-van-atuan-9789031502592","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000521870_De_tomben_van_Atuan_0_0.jpg","checkedAt":"2026-10-31T22:48:08.886Z","sha256":"3ca0339cd11c8a763266128641a91a76324c7254d62d37e53b1672fdaa2f84f6","bytes":281141,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100013,"language":"nl","bound_author_id":921300017,"text":"Sperwer zoekt in het labyrint van Atuan naar het ontbrekende deel van een ring die vrede moet brengen. Zijn aanwezigheid brengt hem in het domein van de hogepriesteres Arha. Hun ontmoeting verbindt een concrete zoektocht met de vraag welke ruimte een vreemdeling binnen haar wereld krijgt. Dit tweede Aardzee-verhaal concentreert zich op de verhouding tussen de bezoeker, zijn opdracht en de bewaakster van de tomben.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1019297/de-tomben-van-atuan.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789024558506","key":{"isbn_13":"9789024558506"},"before":null,"after":{"work_id":975100014,"title":"Hart van de Winter","isbn_13":"9789024558506","isbn_10":"9024558506","language":"nld","publisher":"Luitingh-Sijthoff B.V., Uitgeverij","id":975200084}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024558506","key":{"edition_id":"@edition:9789024558506"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-01-20261101","evidence":[{"url":"https://metadata.is